// Builds maps/builtin-maps.js from the JSON maps, so the app (which may be opened straight from disk, where fetch()
// of local files is blocked) has them built in.   Run:  node maps/build-maps.js
const fs = require("fs"), path = require("path");
const dir = __dirname, out = {};
const pe = JSON.parse(fs.readFileSync(path.join(dir, "play-electric.json"), "utf8"));
out["71"] = { entries: pe.entries, ignored: pe.ignored, created: pe.created };
fs.writeFileSync(path.join(dir, "builtin-maps.js"),
  "// GENERATED by maps/build-maps.js from maps/play-electric.json — edit the JSON, then run: node maps/build-maps.js\n" +
  "// Built-in device maps, keyed by product byte (71 = Play Electric). The user's own map (Mapper) is merged on top.\n" +
  "window.PS_BUILTIN_MAPS = " + JSON.stringify(out) + ";\n");
console.log("builtin-maps.js:", Object.keys(pe.entries).length, "entries,", pe.ignored.length, "ignored");
